// convertPlaceholders converts SQLite-style ? placeholders to PostgreSQL-style $1, $2, etc.
// when running on PostgreSQL
func (t *ItemRegister) convertPlaceholders(sql string, count int) string {
	if t.dbType != database.DBTypePostgres {
		return sql
	}
	result := sql
	for i := 1; i <= count; i++ {
		result = strings.Replace(result, "?", fmt.Sprintf("$%d", i), 1)
	}
	return result
}

// Get retrieves a record from the database by primary key (interface{} for generic API)
// For single primary key: pass the value directly (string, int, etc.)
// For composite keys: pass a map[string]interface{} with field names as keys
func (t *ItemRegister) Get(primaryKey interface{}) bool {
	// Handle composite primary key (map[string]interface{})
	if pkMap, ok := primaryKey.(map[string]interface{}); ok {
		var noVal int
		if v, exists := pkMap["no"]; exists {
			switch val := v.(type) {
			case int:
				noVal = val
			case float64:
				noVal = int(val)
			case string:
				// the key part as text: the API's "CUSTOMER1,10000"
				if n, err := strconv.Atoi(strings.TrimSpace(val)); err == nil {
					noVal = n
				}
			}
		}
		return t.GetByPK(noVal)
	}
	// Handle single primary key (for tables with only one PK field)
	switch pk := primaryKey.(type) {
	case int:
		return t.GetByPK(pk)
	case float64:
		return t.GetByPK(int(pk))
	case string:
		var intVal int
		if _, err := fmt.Sscanf(pk, "%d", &intVal); err == nil {
			return t.GetByPK(intVal)
		}
	}

	fmt.Printf("Error: Invalid primary key type for Item_Register.Get: %T (use map for composite keys)\n", primaryKey)
	return false
}

// GetByPK retrieves a record by its typed primary key(s) - for direct typed access
func (t *ItemRegister) GetByPK(no int) bool {
	tableName := fmt.Sprintf("%s$%s", t.company, ItemRegisterTableName)
	var noVal int
	var from_entry_noVal int
	var to_entry_noVal int
	var creation_dateNull sql.NullString
	var source_codeNull sql.NullString
	var user_idNull sql.NullString
	var journal_batch_nameNull sql.NullString
	var from_phys_inventory_entry_noVal int
	var to_phys_inventory_entry_noVal int

	// Collect arguments for query
	args := []interface{}{
		no,
	}

	// Build SQL with placeholders
	sqlStr := fmt.Sprintf(`SELECT no, from_entry_no, to_entry_no, creation_date, source_code, user_id, journal_batch_name, from_phys_inventory_entry_no, to_phys_inventory_entry_no FROM "%s" WHERE 1=1 AND no = ?`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))
	sqlStr += t.forUpdate()

	err := t.exec().QueryRow(sqlStr, args...).Scan(
		&noVal,
		&from_entry_noVal,
		&to_entry_noVal,
		&creation_dateNull,
		&source_codeNull,
		&user_idNull,
		&journal_batch_nameNull,
		&from_phys_inventory_entry_noVal,
		&to_phys_inventory_entry_noVal,
	)

	if err != nil {
		if err == sql.ErrNoRows {
			// Record not found - this is not an error, just return false
			return false
		}
		// Actual database error
		fmt.Printf("Error: Failed to get Item_Register: %v\n", err)
		return false
	}

	// Populate fields
	t.No = noVal
	t.From_entry_no = from_entry_noVal
	t.To_entry_no = to_entry_noVal
	t.Creation_date, _ = types.NewDateFromString(creation_dateNull.String)
	t.Source_code = types.NewCode(source_codeNull.String)
	t.User_id = types.NewCode(user_idNull.String)
	t.Journal_batch_name = types.NewCode(journal_batch_nameNull.String)
	t.From_phys_inventory_entry_no = from_phys_inventory_entry_noVal
	t.To_phys_inventory_entry_no = to_phys_inventory_entry_noVal

	// Store old values for field tracking
	t.StoreOldValues()

	return true
}

// Insert inserts the record into the database
func (t *ItemRegister) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, ItemRegisterTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.No,
		t.From_entry_no,
		t.To_entry_no,
		t.Creation_date,
		t.Source_code,
		t.User_id,
		t.Journal_batch_name,
		t.From_phys_inventory_entry_no,
		t.To_phys_inventory_entry_no,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (no, from_entry_no, to_entry_no, creation_date, source_code, user_id, journal_batch_name, from_phys_inventory_entry_no, to_phys_inventory_entry_no) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (no) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Item_Register: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(ItemRegisterTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *ItemRegister) InsertAll(records []*ItemRegister, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.No,
			r.From_entry_no,
			r.To_entry_no,
			r.Creation_date,
			r.Source_code,
			r.User_id,
			r.Journal_batch_name,
			r.From_phys_inventory_entry_no,
			r.To_phys_inventory_entry_no,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, ItemRegisterTableName)
	columns := []string{"no", "from_entry_no", "to_entry_no", "creation_date", "source_code", "user_id", "journal_batch_name", "from_phys_inventory_entry_no", "to_phys_inventory_entry_no"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *ItemRegister) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("no") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, ItemRegisterTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("no") {
			setClauses = append(setClauses, "no = ?")
			values = append(values, t.No)
		}
		if t.hasFieldChanged("from_entry_no") {
			setClauses = append(setClauses, "from_entry_no = ?")
			values = append(values, t.From_entry_no)
		}
		if t.hasFieldChanged("to_entry_no") {
			setClauses = append(setClauses, "to_entry_no = ?")
			values = append(values, t.To_entry_no)
		}
		if t.hasFieldChanged("creation_date") {
			setClauses = append(setClauses, "creation_date = ?")
			values = append(values, t.Creation_date)
		}
		if t.hasFieldChanged("source_code") {
			setClauses = append(setClauses, "source_code = ?")
			values = append(values, t.Source_code)
		}
		if t.hasFieldChanged("user_id") {
			setClauses = append(setClauses, "user_id = ?")
			values = append(values, t.User_id)
		}
		if t.hasFieldChanged("journal_batch_name") {
			setClauses = append(setClauses, "journal_batch_name = ?")
			values = append(values, t.Journal_batch_name)
		}
		if t.hasFieldChanged("from_phys_inventory_entry_no") {
			setClauses = append(setClauses, "from_phys_inventory_entry_no = ?")
			values = append(values, t.From_phys_inventory_entry_no)
		}
		if t.hasFieldChanged("to_phys_inventory_entry_no") {
			setClauses = append(setClauses, "to_phys_inventory_entry_no = ?")
			values = append(values, t.To_phys_inventory_entry_no)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "from_entry_no = ?")
		values = append(values, t.From_entry_no)
		setClauses = append(setClauses, "to_entry_no = ?")
		values = append(values, t.To_entry_no)
		setClauses = append(setClauses, "creation_date = ?")
		values = append(values, t.Creation_date)
		setClauses = append(setClauses, "source_code = ?")
		values = append(values, t.Source_code)
		setClauses = append(setClauses, "user_id = ?")
		values = append(values, t.User_id)
		setClauses = append(setClauses, "journal_batch_name = ?")
		values = append(values, t.Journal_batch_name)
		setClauses = append(setClauses, "from_phys_inventory_entry_no = ?")
		values = append(values, t.From_phys_inventory_entry_no)
		setClauses = append(setClauses, "to_phys_inventory_entry_no = ?")
		values = append(values, t.To_phys_inventory_entry_no)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["no"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.No)
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND no = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify Item_Register: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *ItemRegister) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "no":
		if old, ok := oldValue.(int); ok {
			return t.No != old
		}
		return true // Type mismatch, assume changed
	case "from_entry_no":
		if old, ok := oldValue.(int); ok {
			return t.From_entry_no != old
		}
		return true // Type mismatch, assume changed
	case "to_entry_no":
		if old, ok := oldValue.(int); ok {
			return t.To_entry_no != old
		}
		return true // Type mismatch, assume changed
	case "creation_date":
		if old, ok := oldValue.(types.Date); ok {
			return !t.Creation_date.Equal(old)
		}
	case "source_code":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Source_code.Equal(old)
		}
	case "user_id":
		if old, ok := oldValue.(types.Code); ok {
			return !t.User_id.Equal(old)
		}
	case "journal_batch_name":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Journal_batch_name.Equal(old)
		}
	case "from_phys_inventory_entry_no":
		if old, ok := oldValue.(int); ok {
			return t.From_phys_inventory_entry_no != old
		}
		return true // Type mismatch, assume changed
	case "to_phys_inventory_entry_no":
		if old, ok := oldValue.(int); ok {
			return t.To_phys_inventory_entry_no != old
		}
		return true // Type mismatch, assume changed
	}

	return false
}

